      var mq = matchMedia('(prefers-color-scheme: light)');
      var onMQ = function (e) { if (!load('dt-theme')) setTheme(e.matches ? 'light' : 'dark'); };
      if (mq.addEventListener) mq.addEventListener('change', onMQ);
